FROM attendance_record ar LEFT JOIN sys_user u ON ar.user_id = u.id LEFT JOIN sys_group g ON u.group_id = g.id
AND (u.username LIKE CONCAT('%', #{query.username}, '%') OR u.member_id LIKE CONCAT('%', #{query.username}, '%'))
AND u.group_id = #{query.groupId}
AND ar.check_in_date >= #{query.startDate}
AND ar.check_in_date <= #{query.endDate}
AND ar.check_out_time IS NOT NULL
AND ar.check_out_time IS NULL
AND ar.check_in_time IS NOT NULL
